"""Approved topic map as editable, prepared-only draft. Never publishes to MAX."""
from copy import deepcopy
import json
from pathlib import Path
import urllib.request

PARTIAL = 'Это не полный список. Пока могу показать только проверенные пункты.'
PENDING = 'Для этой задачи у меня пока нет проверенного списка документов. Ниже — подготовительные действия, а не требования к заявлению.'


def configure(config):
    c = deepcopy(config)
    nodes = {n['id']: n for n in c['nodes']}
    c['rules']['prepared_only'] = True
    c['ui']['prepared_only'] = dict(text='Здесь доступны подготовленные памятки и списки. Выберите подходящую кнопку. Чтобы сменить тему, напишите «меню». При непосредственной опасности звоните 112.', category='message', hidden=False, target='')
    if not any(b['id'] == 'rights' for b in c['branches']):
        c['branches'].append(dict(id='rights', title='Мои права', entry='rights', roles=['child','parent','candidate'], status='draft', prompt='', keywords=[]))
    for b in c['branches']:
        if b['id'] in {'documents','housing','money','rights','education','family','benefits'}:
            b['status'] = 'draft'
        if b['id'] == 'family': b['roles'] = ['parent','candidate']
        if b['id'] == 'housing': b['title'] = 'Жильё и быт'
        if b['id'] == 'education': b['title'] = 'Учёба и работа'

    def menu(key, branch, title, choices):
        nodes[key] = dict(id=key, branch=branch, title=title, text=title+'\nВыберите тему.', kind='message',
                          buttons=[dict(label=label,target=target) for label,target in choices]+[dict(label='Главное меню',target=c['menu'])],
                          tasks=[], sources=[], routes=[], conditions=[], next='', adult_text='')

    def card(key, branch, title, intro, items, extra, status='editorial', sources=()):
        # Sources are editorial metadata: terminal cards have exactly two buttons.
        nodes[key] = dict(id=key, branch=branch, title=title, kind='message', text=title+'\n\n'+intro,
                          tasks=items.split('|') if items else [], sources=[], routes=[], conditions=[], next='', adult_text='',
                          buttons=[dict(label='Что ещё может понадобиться',target=key+'_extra'),
                                   dict(label='Напомнить',target='reminder_new',values={'reminder_text':'Вернуться к выбранному чек-листу.'})],
                          content_status=status, editorial_sources=list(sources))
        nodes[key+'_extra'] = dict(id=key+'_extra',branch=branch,title=title+' — дополнение',kind='message',text=extra,
                                  tasks=[],sources=[],buttons=[],routes=[],conditions=[],next='',adult_text='')

    menu('documents','documents','Документы',[
        ('Документы при выпуске из детдома','exit_docs'),('Паспорт и свидетельство о рождении','identity'),
        ('СНИЛС и ИНН','numbers'),('Госуслуги','gosuslugi'),('Потерял документ','lost'),
        ('Регистрация','registration'),('Собрать документы для задачи','documents_tasks')])
    menu('identity','documents','Паспорт и свидетельство о рождении',[('Первый паспорт','passport_first'),('Заменить паспорт','passport_replace'),('Свидетельство о рождении','birth')])
    menu('numbers','documents','СНИЛС и ИНН',[(t,k) for k,t in [('snils','Узнать СНИЛС'),('snils_proof','Подтверждение СНИЛС'),('inn','Узнать ИНН'),('inn_proof','Подтверждение ИНН')]])
    menu('gosuslugi','documents','Госуслуги',[('Создать и подтвердить учётную запись','gu_create'),('Восстановить доступ','gu_recover'),('Защитить учётную запись','gu_safe')])
    menu('lost','documents','Какой документ потерян?',[('Паспорт','passport_lost'),('Свидетельство о рождении','birth'),('СНИЛС','snils_proof'),('ИНН','inn_proof'),('Аттестат или диплом','diploma_lost')])
    menu('registration','documents','Регистрация',[('По месту жительства','reg_home'),('По месту пребывания','reg_stay'),('В общежитии','reg_dorm')])
    menu('documents_tasks','documents','Для какой задачи нужны документы?',[('Жильё','docs_housing'),('Выплаты','benefits'),('Учёба','admission'),('Работа','employment_docs'),('Семья','docs_family')])
    nodes['documents_tasks']['buttons'][-2]['conditions']=[dict(field='role',op='ne',value='child')]
    for key,title,items,extra in [
        ('passport_first','Первый паспорт','Записать дату рождения и проверить, есть ли свидетельство о рождении.|Открыть описание оформления первого паспорта на официальном портале.','Полный комплект, способ обращения и требования к фотографиям ещё проверяются. Не заказывайте платное «ускорение» через неизвестных посредников.'),
        ('passport_replace','Заменить паспорт','Определить причину замены: возраст, изменение данных или повреждение.|Проверить, какие прежние документы сохранились.','Для разных причин замены требования отличаются. Сроки, госпошлина и полный комплект пока не подтверждены в этой базе.'),
        ('passport_lost','Потерян паспорт','Записать, когда обнаружена потеря и какие ещё документы пропали.|Если пропала банковская карта, отдельно заблокировать её через свой банк.','Порядок заявления об утрате, выдачи временного удостоверения и замены ещё проверяется. Список для обычной замены нельзя автоматически применять к утрате.'),
        ('birth','Свидетельство о рождении','Записать ФИО при рождении, дату и место рождения.|Уточнить, нужен свой документ или документ ребёнка.','Получение повторного свидетельства и исправление записи — разные задачи. Полный перечень для каждой из них ещё не подготовлен.'),
        ('snils','Узнать СНИЛС','Проверить имеющееся уведомление о регистрации в системе учёта.|Посмотреть свои сведения в личном кабинете Госуслуг, если есть доступ.','Номер и документ, подтверждающий регистрацию, — не одно и то же. Не передавайте доступ к личному кабинету посредникам.'),
        ('snils_proof','Подтверждение СНИЛС','Проверить, сохранилось ли бумажное или электронное уведомление.|Записать, для какой задачи просят подтверждение.','Состав документов для получения подтверждения ещё проверяется; здесь нет требования обязательно иметь пластиковую карточку.'),
        ('inn','Узнать ИНН','Проверить свои имеющиеся налоговые документы.|Открыть официальный сайт ФНС самостоятельно.','Не оплачивайте неизвестному сайту только обещание найти ваш номер. Точную ссылку на нужный сервис ещё проверяем.'),
        ('inn_proof','Подтверждение ИНН','Уточнить, нужен номер или документ о постановке на учёт.|Проверить уже имеющиеся бумажные и электронные документы.','Не предполагаем, что бумажное свидетельство обязательно для любой задачи. Текущий способ получения подтверждения ещё проверяется.'),
        ('diploma_lost','Потерян аттестат или диплом','Записать название учебного заведения, год окончания и прежние ФИО.|Найти сохранившиеся сведения о номере документа, если они есть.','Это подготовка, а не обязательные приложения. Правила дубликата и случай закрытия учебного заведения ещё нужно проверить.'),
        ('reg_home','Регистрация по месту жительства','Определить, на каком основании человек живёт в помещении.|Посмотреть имеющийся договор или документ о праве на жильё.','Регистрация и собственность — разные вещи. Комплект зависит от возраста, основания проживания и согласий.'),
        ('reg_stay','Регистрация по месту пребывания','Записать адрес и предполагаемый срок проживания.|Посмотреть условия договора проживания.','Сроки, исключения и согласия пока не сверены для всех ситуаций; универсального комплекта здесь нет.'),
        ('reg_dorm','Регистрация в общежитии','Найти договор проживания и документ о заселении.|Проверить памятку своего общежития о регистрации.','Заселение и регистрация — разные процедуры. Список справок из другого общежития может не подойти.')]:
        card(key,'documents',title,PENDING,items,extra,'incomplete')
    for key,title,items,extra in [
        ('gu_create','Создать учётную запись','Открыть официальный портал: https://www.gosuslugi.ru/|Выбрать регистрацию и следовать подсказкам портала.|Указывать только свой телефон и доступную почту.','Это общая ссылка на портал, не прямая ссылка на услугу. Способы подтверждения нужно смотреть в самом портале.'),
        ('gu_recover','Восстановить доступ','Вручную открыть https://www.gosuslugi.ru/|На экране входа выбрать восстановление доступа.|Проверить, есть ли доступ к своему телефону и почте.','Если привычный способ недоступен, используйте справку самого портала. Бот не восстанавливает учётную запись и не запрашивает коды.'),
        ('gu_safe','Защитить учётную запись','Использовать отдельный пароль.|Проверить актуальность своего телефона и почты.|Никому не сообщать пароль и коды входа.','Проверьте доступные настройки защиты в личном кабинете. Не входите по ссылке от неизвестного собеседника.')]:
        card(key,'documents',title,'Памятка для самостоятельных действий.',items,extra)

    menu('housing','housing','Жильё и быт',[('Выхожу из детского дома','exit_docs'),('Жильё от государства','state_housing'),('Права на полученную квартиру','housing_rights'),('Снимаю жильё','rent'),('Коммунальные платежи','utilities'),('Быт и безопасность','household'),('Не пускают домой / негде жить','housing_problem')])
    menu('state_housing','housing','Жильё от государства',[('Включение в список','housing_list'),('Уже в списке','housing_wait'),('Получаю квартиру','housing_receive'),('Переезжаю в другой регион','housing_move')])
    menu('docs_housing','housing','Документы для жилья',[('При выпуске из детдома','exit_docs'),('Включение в список','housing_list'),('При переезде','housing_move'),('При получении квартиры','housing_receive'),('Жильё уже получил','housing_rights'),('Для аренды','rent_contract')])
    menu('housing_rights','housing','На каком основании предоставлена квартира?',[('Специализированный наём','special_rent'),('Социальный наём','social_rent'),('Собственность','ownership')])
    menu('rent','housing','Снимаю жильё',[('До просмотра','rent_view'),('Проверить договор','rent_contract'),('Перед заселением','rent_in'),('Выезжаю','rent_out')])
    menu('utilities','housing','Коммунальные платежи',[('Разобраться в квитанции','bill'),('Показания счётчиков','meters'),('Оплата','bill_pay'),('Непонятный долг','bill_debt')])
    menu('household','housing','Быт и безопасность',[('Первые покупки','purchases'),('Уборка и стирка','clean'),('Еда и хранение','food'),('Соседи','neighbors'),('Газ или протечка','emergency_home')])
    menu('housing_problem','housing','Проблема с жильём',[('Есть угроза сейчас','threat'),('Нет места для ночлега','shelter'),('Спор о проживании','residence_dispute')])
    card('exit_docs','housing','Выхожу из детского дома',PENDING,
         'Проверить, какие личные документы уже находятся на руках.|Составить отдельный список документов о жилье и имуществе, которые есть.|Записать, какие документы об учёбе и здоровье уже выданы.',
         'Полный перечень выдаваемого при выпуске проверяется по правилам ведения личных дел. Сам факт выпуска не подтверждает право на квартиру. Жилищные условия определяет статья 8 закона № 159-ФЗ. Отдельно нужно проверить поддержку при выпуске и условия временного проживания.','incomplete')
    for key,title,items,extra in [
        ('housing_list','Включение в список на жильё','Проверить имеющиеся документы о личности и статусе.|Отдельно выписать, есть ли собственность или право проживания по социальному найму.|Сохранить копию уже поданного заявления, если оно есть.','Это подготовительная памятка. Актуальный перечень приложений и региональные особенности ещё проверяются. Право не определяется только проживанием в детском доме.'),
        ('housing_wait','Уже включён в список','Сохранить имеющееся подтверждение включения.|Проверить, актуальны ли ФИО и контактные сведения в собственных документах.|Отдельно записать, что изменилось: место жительства, семья или жилищные права.','Бот не проверяет очередь и не знает срок предоставления квартиры. Порядок актуализации сведений ещё проверяется.'),
        ('housing_receive','Получаю квартиру','Прочитать, какой вид договора предлагается.|Сверить адрес и описание помещения в документах.|До подписания акта записать замеченные недостатки.','Храните свой экземпляр подписанных документов. Точный комплект при предоставлении и процедура исправления недостатков ещё проверяются.'),
        ('housing_move','Переезжаю в другой регион','Сохранить имеющиеся сведения о включении в прежнем регионе.|Записать новое место жительства и имеющиеся документы о проживании.|Отделить намерение переехать от уже состоявшегося переезда.','Не подавайте отдельное заявление об исключении только по этой памятке. Порядок перевода между списками требует проверки; перечень приложений здесь пока не дан.'),
        ('special_rent','Специализированный наём','Найти свой договор.|Посмотреть срок договора и обязанности нанимателя.|Сохранить документы передачи квартиры.','Специализированный наём сам по себе не означает собственность. Истечение пяти лет не делает квартиру автоматически пригодной для продажи.'),
        ('social_rent','Социальный наём','Проверить название договора.|Посмотреть, кто указан нанимателем и кто имеет право проживания.|Сохранить экземпляр договора.','Социальный наём не равен собственности. Условия приватизации и распоряжения квартирой здесь ещё не подготовлены.'),
        ('ownership','Собственность','Найти документ о возникновении права.|Сопоставить его со сведениями о зарегистрированном праве, если они есть.|Перед сделкой отдельно проверить доли и ограничения.','Владение документом или проживание в квартире не заменяет проверку права. Индивидуальный вывод о допустимости продажи бот не даёт.')]:
        card(key,'housing',title,PENDING,items,extra,'incomplete')
    for key,title,items,extra in [
        ('rent_view','До просмотра квартиры','Сравнить адрес, цену и условия объявления.|Записать, кто сдаёт квартиру и на каком основании.|Не переводить деньги только за обещание показать жильё.','Заранее уточните коммунальные платежи, обеспечительный платёж и условия возврата. Бот не ищет и не проверяет объявления.'),
        ('rent_contract','Проверить договор аренды','Сверить участников и адрес квартиры.|Прочитать сумму, даты и способ оплаты.|Найти условия обеспечительного платежа и выезда.|Убедиться, что устные договорённости записаны.','Это список для чтения договора, не подтверждение его законности. Отдельно сверяют полномочия сдающего и права других лиц.'),
        ('rent_in','Перед заселением','Зафиксировать состояние квартиры и имущества.|Записать показания счётчиков.|Сверить количество переданных ключей.|Сохранить договор и подтверждения платежей.','Замеченные повреждения лучше отразить в документе передачи вместе с другой стороной. Уточните, как сообщать о поломках.'),
        ('rent_out','Выезжаю из съёмной квартиры','Прочитать условия и срок уведомления в своём договоре.|Согласовать дату передачи ключей.|Зафиксировать состояние квартиры и счётчики.|Сохранить расчёт по платежам.','Проверьте условие возврата обеспечительного платежа. Бот не определяет, законно ли удержание в конкретном споре.'),
        ('bill','Разобраться в квитанции','Сверить адрес и расчётный период.|Разделить текущие начисления, прежний долг и пени.|Сравнить объём потребления с показаниями.','Сохраните предыдущую квитанцию и чеки. Не считайте все суммы в квитанции платой только за текущий месяц.'),
        ('meters','Передать показания','Убедиться, какой счётчик относится к нужному ресурсу.|Записать дату и показания.|Проверить срок и способ передачи в своей квитанции.','Не заменяйте показания предполагаемым расходом. Правила снятия конкретного прибора посмотрите в инструкции.'),
        ('bill_pay','Оплатить коммунальные услуги','Сверить получателя, адрес и лицевой счёт.|Проверить сумму и комиссию до подтверждения.|Сохранить чек.','Не используйте реквизиты из случайного сообщения. Срок зачисления уточняется в выбранном способе оплаты.'),
        ('bill_debt','Непонятный долг','Собрать квитанции за спорный период.|Сопоставить их с сохранёнными чеками.|Записать, какая именно сумма не сходится.','Не оплачивайте повторно только из-за неизвестного сообщения. Эта памятка помогает подготовить сведения, но не устанавливает наличие долга.'),
        ('purchases','Первые покупки для дома','Проверить, что уже есть в квартире.|Выделить необходимое для сна, еды и гигиены.|Составить короткий список покупок в пределах доступной суммы.','Мебель и технику можно планировать отдельно. Не считайте перечень покупок перечнем вещей, которые обязаны выдать при выпуске.'),
        ('clean','Уборка и стирка','Разделить дела на ежедневные и еженедельные.|Посмотреть ярлыки одежды перед стиркой.|Использовать средство по инструкции на упаковке.','Не смешивайте бытовые чистящие средства. Для новой техники сначала прочитайте инструкцию.'),
        ('food','Еда и хранение','Проверить сроки годности.|Соблюдать условия хранения на упаковке.|Составить небольшой список продуктов под план питания.','Планируйте покупки с учётом холодильника и возможности готовить. При сомнениях в безопасности продукта не пробуйте его для проверки.'),
        ('neighbors','Договориться с соседями','Спокойно описать конкретную проблему.|Предложить понятную договорённость.|Записать, когда и что повторяется, если договориться не получилось.','Региональные часы тишины здесь ещё не проверены. При угрозе безопасности не продолжайте конфликт.'),
        ('emergency_home','Газ или протечка','При непосредственной опасности выйти в безопасное место.|Позвонить 112 и сообщить адрес и что произошло.|Следовать указаниям диспетчера.','Не откладывайте срочные действия до напоминания. Подробные инструкции для газа, воды и электричества ещё проходят отдельную проверку.'),
        ('threat','Есть угроза сейчас','Если возможно, перейти в безопасное место.|Позвонить 112 при непосредственной опасности.|Сообщить доверенному человеку, где нужна помощь.','Не откладывайте помощь ради сбора документов. Бот не вызывает экстренные службы; напоминание не заменяет звонок.'),
        ('shelter','Нет места для ночлега','Если есть угроза жизни или здоровью, позвонить 112.|Связаться с доверенным человеком и сообщить о ситуации.|Проверить, есть ли безопасное временное место.','Проверенной универсальной ссылки на реестр мест ночлега в этой карточке пока нет. Бот не ищет места и не обещает заселение.'),
        ('residence_dispute','Спор о проживании','Сохранить имеющийся договор или документы о праве на жильё.|Записать, что произошло и когда.|При непосредственной угрозе сначала обеспечить безопасность.','Эта памятка не устанавливает законность выселения. Подробный правовой список ещё проверяется.')]:
        card(key,'housing',title,'Памятка по выбранной ситуации.',items,extra)

    menu('money','money','Деньги',[('Первые самостоятельные расходы','first_money'),('Банковские карты','cards'),('Налоги','tax'),('Защита от мошенников','fraud'),('Мой бюджет','budget')])
    groups=[('first_money','Первые самостоятельные расходы',[('На что нужны деньги','money_needs'),('Получил крупную сумму','money_large'),('Не хватает на необходимое','money_short')]),('cards','Банковские карты',[('Дебетовая и кредитная','card_types'),('Оформление','card_open'),('Комиссии','card_fees'),('Потерял карту','card_lost')]),('tax','Налоги',[('С зарплаты','tax_salary'),('На имущество и транспорт','tax_property'),('Самозанятость','tax_self'),('Уведомление','tax_notice')]),('fraud','Защита от мошенников',[('Подозрительный звонок','fraud_call'),('Просят карту или код','fraud_code'),('Подозрительная работа','fraud_job'),('Уже передал деньги или данные','fraud_loss')]),('budget','Мой бюджет',[('На неделю','budget_week'),('На месяц','budget_month'),('Нерегулярный доход','budget_irregular'),('Резерв','budget_reserve')])]
    for key,title,choices in groups: menu(key,'money',title,choices)
    for key,title,items,extra in [
        ('money_needs','На что нужны деньги','Выписать необходимые расходы: питание, жильё, транспорт и связь.|Сопоставить их с доступной суммой.|Отделить обязательное от покупок, которые могут подождать.','Не копируйте чужой бюджет без учёта своей ситуации.'),
        ('money_large','Получил крупную сумму','Записать, на какой срок должна хватить сумма.|Отложить деньги на ближайшие обязательные платежи.|Не принимать решение о крупной покупке под давлением.','Разовая выплата не равна ежемесячному доходу. Бот не рекомендует инвестиции или кредит.'),
        ('money_short','Не хватает на необходимое','Определить ближайшие расходы на еду, жильё и дорогу.|Посмотреть, какие траты можно перенести.|Открыть в меню раздел выплат и проверить подготовленные темы.','Наличие раздела выплат не означает, что выплата уже положена. Право и условия проверяются отдельно.'),
        ('card_types','Дебетовая и кредитная карты','Прочитать в договоре, используются свои или заёмные деньги.|Проверить наличие кредитного лимита или овердрафта.|Перед использованием изучить условия процентов и платежей.','Название карты и реклама не заменяют договор. Подбор банка и кредитного продукта бот не делает.'),
        ('card_open','Оформление карты','Сравнить стоимость обслуживания.|Проверить условия переводов и снятия наличных.|Уточнить требования к возрасту и документам на официальном сайте банка.','Единого списка документов для всех возрастов и банков в этой базе нет.'),
        ('card_fees','Комиссии по карте','Проверить плату за обслуживание и уведомления.|Посмотреть комиссии за переводы и наличные.|Найти условия отмены платных дополнительных услуг.','Условие «бесплатно» может зависеть от оборота или остатка. Читайте тариф целиком.'),
        ('card_lost','Потерял банковскую карту','Самостоятельно открыть приложение своего банка или использовать его официальный номер.|Заблокировать потерянную карту.|Посмотреть последние операции.','Если есть неизвестные операции, сообщите об этом банку сразу. Сроки и порядок оспаривания требуют отдельной проверки; возврат не гарантируется.'),
        ('fraud_call','Подозрительный звонок','Завершить разговор, если требуют срочно перевести деньги или назвать код.|Самостоятельно открыть официальный контакт банка или сервиса.|Проверить сообщение через этот канал.','Номер на экране сам по себе не доказывает, кто звонит.'),
        ('fraud_code','Просят карту или код','Не сообщать PIN, пароль и одноразовые коды.|Не передавать карту или доступ к приложению другому человеку.|Прекратить действие, если непонятно, что подтверждает код.','Передача реквизитов для получения перевода не требует сообщения кода входа или подтверждения операции.'),
        ('fraud_job','Подозрительная работа','Проверить, кто предлагает работу и что входит в обязанности.|Не платить за обещание вакансии неизвестному посреднику.|Не соглашаться передавать свою карту или проводить чужие деньги.','Сохраните описание предложения. Реальные вакансии бот ищет только через раздел поиска работы.'),
        ('fraud_loss','Уже передал деньги или данные','Сразу связаться со своим банком через официальный канал, если затронуты деньги или карта.|Сменить скомпрометированный пароль через официальный сервис.|Сохранить сообщения, чеки и сведения об операции.','Не платите людям, обещающим гарантированно вернуть деньги. Дальнейшие сроки и процедуры нужно проверять по конкретному случаю.'),
        ('budget_week','Бюджет на неделю','Записать доступную сумму.|Отложить деньги на обязательные платежи недели.|Распределить оставшееся на питание, дорогу и другие нужды.','В конце недели сравните план с расходами. Финансовые записи бот не хранит.'),
        ('budget_month','Бюджет на месяц','Записать ожидаемые доходы и даты.|Выписать постоянные платежи.|Разделить оставшееся между неделями.|Отдельно учесть нерегулярные расходы.','Простой шаблон: доходы − обязательные расходы − планируемые покупки = остаток. Не считайте неопределённый доход уже полученным.'),
        ('budget_irregular','Нерегулярный доход','Записать деньги, которые уже получены.|Определить минимальные обязательные расходы до следующего поступления.|Планировать необязательные покупки после поступления денег.','Для редких крупных платежей можно заранее выделять часть каждого поступления.'),
        ('budget_reserve','Резерв на непредвиденное','Определить небольшую посильную сумму.|Отделить резерв от денег на текущие покупки.|Записать, для каких ситуаций он предназначен.','Размер резерва зависит от возможностей. Не берите заём только ради создания резерва.')]:
        card(key,'money',title,'Короткая памятка.',items,extra)
    for key,title,items,extra in [
        ('tax_salary','Налог с зарплаты','Посмотреть начисленную сумму и удержания в расчётном листке.|Отделить сумму до налога от суммы к выплате.','Ставка не всегда равна 13%. Индивидуальный расчёт и вычеты эта карточка не выполняет.'),
        ('tax_property','Имущество и транспорт','Сверить объекты в своём уведомлении.|Проверить период, долю и сумму по каждому объекту.','Льготы и ставки могут зависеть от налога и территории; универсального освобождения для всех выпускников здесь не заявляем.'),
        ('tax_self','Самозанятость','Записать, какую деятельность планируется вести.|Проверить её условия на официальном сайте ФНС до регистрации.','Условия применения режима, ограничения и влияние на поддержку ещё не подготовлены. Не регистрируйтесь только по этой краткой памятке.'),
        ('tax_notice','Налоговое уведомление','Проверить свои сведения, объекты и налоговый период.|Сверить срок и реквизиты в официальном уведомлении.','Разъяснение ФНС: https://www.nalog.gov.ru/nu/ — справочная страница, а не доступ бота к вашему начислению.')]:
        card(key,'money',title,'Общая подготовка. Полный налоговый сценарий ещё проверяется.',items,extra,'incomplete')

    menu('rights','rights','Мои права',[('Права простыми словами','rights_basics'),('Ответственность за поступки','responsibility'),('Договоры и подписи','contracts'),('Поддержка выпускникам','graduate_support'),('Общение с полицией','police'),('Покупки и услуги','consumer')])
    for key,title,choices in [
        ('rights_basics','Права простыми словами',[('Как разобраться в праве','rights_simple'),('Как читать закон','read_law')]),
        ('responsibility','Ответственность за поступки',[('До 18 лет','responsibility_minor'),('С 18 лет','responsibility_adult'),('Опасные предложения','fraud_job')]),
        ('contracts','Договоры и подписи',[('Перед подписью','contract_sign'),('Электронное подтверждение','contract_electronic'),('Доверенность','power')]),
        ('graduate_support','Поддержка выпускникам',[('Жильё','state_housing'),('Учёба','education_support'),('Выплаты','benefits'),('Работа','first_job')]),
        ('police','Общение с полицией',[('Проверка документов','police_id'),('Доставление или задержание','police_detain'),('Сообщить о происшествии','police_report')]),
        ('consumer','Покупки и услуги',[('Вещь не подошла','consumer_fit'),('Есть недостаток','consumer_defect'),('Покупка в интернете','consumer_online'),('Подписки','consumer_sub')])]: menu(key,'rights',title,choices)
    for key,title,items,extra in [
        ('rights_simple','Как разобраться в праве','Описать ситуацию: что произошло, когда и с кем.|Отделить имеющиеся документы от устных обещаний.|Найти правило именно для своей ситуации.','Одинаковые бытовые слова могут обозначать разные юридические процедуры. Подготовленные темы доступны в меню.'),
        ('read_law','Как читать закон','Проверить название и номер закона.|Проверить действующую редакцию и дату вступления нормы в силу.|Прочитать условия и исключения рядом с нужной статьёй.','Смотрите также регион, возраст и статус, к которым относится правило. Не применяйте будущие изменения раньше срока.'),
        ('responsibility_minor','Ответственность до 18 лет','Записать свой точный возраст.|Отделить предложение что-то сделать от уже произошедшего.|При угрозе сначала обеспечить безопасность.','Единого возраста ответственности за все поступки нет. Подробная правовая памятка ещё проверяется; бот не оценивает виновность.'),
        ('responsibility_adult','Ответственность с 18 лет','Не подписывать непонятный документ под давлением.|Прочитать обязательства, суммы и последствия.|Сохранить свой экземпляр документов.','Совершеннолетие не означает одинаковых последствий для любого поступка. Юридическая оценка конкретного события здесь не подготовлена.'),
        ('contract_sign','Перед подписью','Сверить стороны, предмет, стоимость и сроки.|Прочитать ответственность и условия прекращения.|Проверить приложения и незаполненные поля.|Сохранить согласованный экземпляр.','Не подписывайте пустые листы. Если формулировка непонятна, её нужно разобрать до подписи.'),
        ('contract_electronic','Электронное подтверждение','Прочитать, какое действие подтверждается.|Проверить адрес сервиса.|Сохранить условия, которые принимаются.','Код может подтверждать юридически значимое действие. Не сообщайте его собеседнику.'),
        ('power','Доверенность','Определить конкретное действие, которое поручается.|Прочитать полномочия, срок и возможность передоверия.|Сохранить сведения о выданном документе.','Форма, необходимость нотариуса и отмена зависят от ситуации. Полный сценарий ещё проверяется.'),
        ('police_id','Проверка документов','Спокойно уточнить причину обращения.|Не подписывать текст, который не прочитан.|При непосредственной опасности заботиться о безопасности.','Точные полномочия, основания проверки и права несовершеннолетнего ещё проверяются. Эта карточка не является полной правовой инструкцией.'),
        ('police_detain','Доставление или задержание','Уточнить, что именно происходит и на каком основании.|Сообщить, если вам нет 18 лет.|Попросить разъяснить права и возможность юридической помощи.','Сроки и процессуальные правила зависят от основания. Универсальное правило «всегда три часа» здесь не применяется; полный сценарий пока не готов.'),
        ('police_report','Сообщить о происшествии','При непосредственной опасности позвонить 112.|Записать место, время и факты.|Сохранить имеющиеся подтверждения, не подвергая себя опасности.','Точный порядок подачи и подтверждения регистрации обращения ещё проверяется. Бот не передаёт заявление.'),
        ('consumer_fit','Вещь не подошла','Записать дату покупки.|Сохранить товар, упаковку и подтверждение покупки, если оно есть.|Определить, покупали дистанционно или в магазине.','Правила обмена и возврата отличаются; есть исключения по товарам. Полный сценарий ещё проверяется.'),
        ('consumer_defect','У товара есть недостаток','Записать, когда и как обнаружена проблема.|Сохранить описание товара и сведения о покупке.|Зафиксировать недостаток.','Отсутствие чека не следует автоматически считать отсутствием прав. Конкретные требования и сроки ещё проверяются.'),
        ('consumer_online','Покупка в интернете','Сохранить карточку товара и условия заказа.|Записать продавца, дату заказа и доставки.|Проверить полученный товар.','Сроки и правила возврата зависят от обстоятельств. Не переносите на интернет-покупку памятку обычного магазина без проверки.'),
        ('consumer_sub','Платные подписки','Проверить, какой сервис списывает деньги.|Открыть управление подпиской в официальном сервисе.|Сохранить подтверждение отключения и сведения о списании.','Удаление приложения не обязательно отменяет подписку. Условия возврата конкретного платежа ещё нужно проверить.')]:
        card(key,'rights',title,'Памятка для подготовки. Правовые условия конкретного случая здесь не устанавливаются.',items,extra,'incomplete')

    menu('education','education','Учёба и работа',[('Выбрать профессию','career'),('Поступление и поддержка','admission'),('Трудности с учёбой','study_problems'),('Первая работа','first_job'),('Резюме и портфолио','resume'),('Найти работу','work')])
    for key,title,choices in [
        ('career','Выбрать профессию',[('Мои интересы','career_interests'),('Профориентационный тест','career_test'),('Узнать о профессии','career_info'),('Попробовать на практике','career_try')]),
        ('admission','Поступление и поддержка',[('Колледж после 9 класса','college9'),('Колледж после 11 класса','college11'),('Вуз','university'),('Общежитие','dorm'),('Поддержка во время учёбы','education_support')]),
        ('study_problems','Трудности с учёбой',[('Не понимаю предмет','study_subject'),('Учебные долги','study_debts'),('Перевестись','study_transfer'),('Не хватает денег','education_support')]),
        ('first_job','Первая работа',[('Документы для оформления','employment_docs'),('Трудовой договор','job_contract'),('Мне нет 18 лет','job_minor'),('Совмещать с учёбой','job_study')]),
        ('resume','Резюме и портфолио',[('Нет опыта','resume_first'),('Сопроводительное письмо','cover_letter'),('Примеры работ','portfolio')])]: menu(key,'education',title,choices)
    for key,title,items,extra in [
        ('career_interests','Мои интересы','Записать три занятия, которые нравятся.|Отдельно выписать, что получается и чему хочется научиться.|Сравнить несколько профессий с этими интересами.','Интересы можно менять. Не нужно выбирать профессию навсегда за один разговор.'),
        ('career_test','Профориентационный тест','Сначала определить, что хочется узнать о себе.|Выбирать тест с объяснением результата.|Сопоставлять результат с реальными задачами профессии.','Проверенной ссылки на тест в этой карточке пока нет. Результат теста не является обязательным выбором профессии.'),
        ('career_info','Узнать о профессии','Посмотреть обычные задачи специалиста.|Выписать требования к образованию и навыкам.|Сравнить условия нескольких реальных вакансий.','Реальные вакансии доступны через «Найти работу». Одна вакансия не описывает всю профессию.'),
        ('career_try','Попробовать на практике','Выбрать небольшое безопасное учебное задание.|Найти вводный урок или пример задачи.|После выполнения записать, что понравилось и что оказалось трудным.','Пробное задание не должно требовать передачи банковской карты, паролей или оплаты за трудоустройство.'),
        ('study_subject','Не понимаю предмет','Выбрать одну конкретную непонятную тему.|Записать, на каком шаге возникает трудность.|Подготовить вопросы к преподавателю.|Начать с короткого посильного задания.','Полезно отдельно проверить базовые темы, на которых строится новый материал.'),
        ('study_debts','Учебные долги','Составить список невыполненных работ.|Проверить сроки и правила пересдачи в своём учебном заведении.|Разделить подготовку на небольшие шаги.','Не считайте неподтверждённое устное обещание изменением официального срока.'),
        ('study_transfer','Перевестись','Определить желаемую программу.|Сохранить сведения о пройденном обучении.|Проверить правила и доступные места у принимающего учебного заведения.','Не прекращайте текущее обучение только по этой памятке. Документы, сроки и сохранение поддержки ещё проверяются.'),
        ('job_contract','Трудовой договор','Прочитать должность и обязанности.|Проверить оплату, график и место работы.|Сверить дату начала и условия прекращения.|Сохранить свой экземпляр.','Эта памятка не заменяет проверку договора. Не считайте гражданско-правовой договор трудовым только из-за слова «работа».'),
        ('job_minor','Работа до 18 лет','Записать точный возраст и учебный график.|Проверить содержание работы и предложенные часы.|До согласия отдельно проверить возрастные ограничения.','Полный перечень условий, согласий и документов для разных возрастов ещё проверяется. Наличие вакансии не подтверждает, что она подходит несовершеннолетнему.'),
        ('job_study','Совмещать работу с учёбой','Выписать обязательное время учёбы и дорогу.|Определить реально свободные часы.|Сопоставить их с графиком вакансии.','Оставьте время на сон и подготовку. Для несовершеннолетнего отдельно действуют возрастные ограничения.'),
        ('resume_first','Резюме без опыта','Указать желаемую работу и доступный контакт.|Описать образование и учебную практику.|Добавить конкретные навыки и примеры учебных задач.','Не выдумывайте опыт. Паспортные и банковские данные в резюме не нужны.'),
        ('cover_letter','Сопроводительное письмо','Назвать вакансию.|Коротко объяснить интерес к задачам.|Привести один подходящий навык или пример.|Указать готовность обсудить условия.','Не обещайте умения, которых пока нет. Письмо можно сделать коротким.'),
        ('portfolio','Примеры работ','Выбрать несколько работ, которые показывают нужные навыки.|К каждой добавить задачу и свой вклад.|Убрать чужие персональные данные.','Учебные работы допустимо честно назвать учебными. Публикуйте только то, на что у вас есть право.')]:
        card(key,'education',title,'Подготовленный план действий.',items,extra)
    for key,title in [('college9','Колледж после 9 класса'),('college11','Колледж после 11 класса'),('university','Поступление в вуз'),('dorm','Общежитие')]:
        card(key,'education',title,PENDING,'Выбрать программу и учебное заведение.|Сохранить актуальные правила приёма или заселения.|Отдельно выписать сроки и условия выбранного варианта.',
             'Не заказывайте справки заранее по чужому списку. Полный комплект, льготы и правила для выбранного года ещё проверяются.','incomplete')
    card('employment_docs','education','Документы для оформления на работу',PARTIAL,
         'Подготовить паспорт или другой документ, удостоверяющий личность.|Подготовить подтверждение регистрации в системе индивидуального учёта, если оно уже есть.|Если работа не первая — подготовить трудовую книжку и/или сведения о трудовой деятельности.',
         'По статье 65 ТК РФ документы воинского учёта нужны соответствующим категориям; документ об образовании — для работы, требующей специальных знаний. Дополнительные справки зависят от вида работы. При первом трудоустройстве и отсутствии лицевого счёта сведения для регистрации подаёт работодатель. ИНН и банковская карта не включены здесь как универсальные обязательные документы.','partial',
         ['https://www.consultant.ru/document/cons_doc_LAW_34683/b618fae23b33471d3e7e3e373dd93fcced4356b8/'])

    # Existing entry points now lead to the same cards, not divergent older advice.
    menu('benefits','benefits','Выплаты и поддержка',[('При выпуске','release_support'),('Во время учёбы','education_support'),('Пенсия по потере кормильца','pension'),('Поддержка семьи с ребёнком','child_support')])
    menu('education_support','education','Поддержка во время учёбы',[('Стипендия','scholarship'),('Обеспечение во время учёбы','study_provision'),('Общежитие','dorm')])
    menu('family','family','Семья',[('Формы семейного устройства','forms'),('Готовлюсь принять ребёнка','docs_family'),('Документы ребёнка','child_documents')])
    menu('docs_family','family','Документы для будущего родителя',[('Усыновление','adoption'),('Опека или попечительство','guardianship'),('Приёмная семья','foster')])
    for key,branch,title in [('release_support','benefits','Поддержка при выпуске'),('pension','benefits','Пенсия по потере кормильца'),('child_support','benefits','Поддержка семьи с ребёнком'),('scholarship','education','Стипендия'),('study_provision','education','Обеспечение во время учёбы'),('adoption','family','Документы для усыновления'),('guardianship','family','Документы для опеки или попечительства'),('foster','family','Документы для приёмной семьи'),('child_documents','family','Документы ребёнка')]:
        card(key,branch,title,PENDING,'Уточнить точное название выбранной меры или процедуры.|Проверить, какие относящиеся к ней документы уже есть.|Не заказывать платные справки, пока обязательный перечень не подтверждён.',
             'Полный перечень, условия и точная ссылка на оформление ещё проверяются. По этой карточке нельзя заключить, что право уже подтверждено.','incomplete')
    card('forms','family','Формы семейного устройства','Выбор формы требует отдельного понимания прав и обязанностей.',
         'Раздельно изучить усыновление, опеку/попечительство и приёмную семью.|Записать вопросы об обязанностях и оформлении.|После выбора темы открыть соответствующую карточку документов.',
         'Подробное проверенное объяснение различий ещё готовится. Бот не выбирает форму за человека.','incomplete')
    aliases={'docs_benefits':'benefits','docs_education':'admission','benefits_result':'benefits','received':'housing_rights','family_steps':'docs_family','children':'family','adult':'documents_tasks','rejection':'benefits','help':'housing_problem','help_registry':'shelter'}
    for old,target in aliases.items():
        menu(old,nodes[target]['branch'],nodes[target]['title'],[('Открыть тему',target)])
    menu('plan','plan','С чего начать',[('Документы при выпуске','exit_docs'),('Жильё','housing'),('Учёба и работа','education'),('Деньги','money')])
    menu(c['menu'],'start','С чем помочь?',[('Документы','documents'),('Жильё и быт','housing'),('Деньги','money'),('Мои права','rights'),('Учёба и работа','education'),('Выплаты','benefits'),('Семья','family'),('Напоминания','reminders'),('С чего начать','plan')])
    nodes[c['menu']]['buttons'][-1]=dict(label='Начать заново',target=c['start'],values={'reset':True})
    nodes[c['menu']]['text']='Выберите тему. Внутри — готовые памятки и чек-листы. Для поиска вакансий откройте «Учёба и работа» → «Найти работу».'
    # Parent/candidate wording does not silently make child-focused tasks personal.
    nodes['education']['adult_text']='Учёба и работа\nВыберите тему для ребёнка, которому помогаете.'
    c['materials']=[m for m in c.get('materials',[]) if not m['id'].startswith('prepared_')]
    for n in nodes.values():
        if not n.get('content_status'): continue
        source_ids=[]
        for i,url in enumerate(n.get('editorial_sources',[])):
            sid='prepared_'+n['id']+'_'+str(i)
            c['sources'][sid]=dict(title='Основание: '+n['title'],url=url)
            source_ids.append(sid)
        c['materials'].append(dict(id='prepared_'+n['id'],title=n['title'],
            text='Статус: '+n['content_status']+'\n'+n['text']+'\n'+'\n'.join(n['tasks'])+'\nДополнение: '+nodes[n['id']+'_extra']['text'],
            branches=[n['branch']],roles=['parent','candidate'] if n['branch']=='family' else [],regions=[],
            min_age=None,max_age=None,sources=source_ids,checked='2026-09-23' if source_ids else '',review_days=30,enabled=False))
    c['nodes']=list(nodes.values())
    return c


def main():
    from project.llm.services.scenario import validate
    base='http://127.0.0.1:18765'
    before=json.load(urllib.request.urlopen(base+'/api/state'))
    config=validate(configure(before['config']))
    request=urllib.request.Request(base+'/api/draft',data=json.dumps(dict(config=config,revision=before['revision']),ensure_ascii=False).encode(),headers={'Content-Type':'application/json','X-Editor-Request':'local'},method='PUT')
    saved=json.load(urllib.request.urlopen(request))
    after=json.load(urllib.request.urlopen(base+'/api/state'))
    assert after['revision']==saved['revision'] and after['published_id']==before['published_id']
    report=Path('docs/marshrut-review/implemented-draft.md')
    lines=['# Реализованный черновик веток','',f"Редакция {after['revision']}; публикация MAX не менялась ({after['published_id']}).",'',
           'Это версия для проверки навигации и текстов. Неполные юридические карточки явно отмечены. Подготовительные памятки не являются подтверждёнными комплектами документов.', '']
    for n in config['nodes']:
        if n.get('content_status'):
            lines += ['## '+n['title'], '', 'Статус: '+n['content_status'], '', n['text'], '']+['- '+t for t in n['tasks']]+['', '**Что ещё может понадобиться:** '+next(x['text'] for x in config['nodes'] if x['id']==n['id']+'_extra'), '']
    report.write_text('\n'.join(lines),encoding='utf-8')
    print(json.dumps(dict(revision=after['revision'],published_id=after['published_id'],nodes=len(config['nodes']),cards=sum(bool(n.get('content_status')) for n in config['nodes'])),ensure_ascii=False))


if __name__=='__main__': main()
